aufgaben.sysml:
// in Funktionen
action <'F-008'> steigungsueberwachen {
    doc /* Steigung des Fahrweges überwachen und bei Überschreitung der maximalen Steigung die Fahrt anpassen. */
}

// in Logik
part def <'L-009'> Steigungssensor {
    doc /* Sensor, der die Steigung des Fahrweges überwacht. */
}

// in Physik::ftf
part <'P-009'> steigungsensor : Logik::Steigungssensor;

// in Logik
part def <'L-009'> Breitsensor {
    doc /* Sensor zur Überwachung der Fahrzeugbreite. */
}

// in Physik::ftf
part <'P-009'> ftfBreitsensor : Logik::Breitsensor;

// in Funktionen
action <'F-008'> ladestandUnter15NeuauftragVerhindern {
    doc /* Verhindert das Annehmen neuer Fahraufträge, wenn der Akkuladestand unter 15 % liegt. */
}

// in Funktionen
action <'F-008'> zustandsMelden {
    doc /* Das FTF meldet Position, Ladestand und Störungen mindestens einmal pro Sekunde an das Leitsystem. */
}

// in Funktionen
action <'F-008'> verbindungsverlustKontrollieren {
    doc /* Verbindungsverlust von mehr als 5 Sekunden kontrolliert anhalten. */
}

// in Logik
part def <'L-009'> VerbindungsverlustSensor {
    doc /* Sensor, der den Verbindungsstatus überwacht und einen Verbindungsverlust meldet. */
}

// in Physik::ftf
part <'P-009'> verbindungsverlustSensor : Logik::VerbindungsverlustSensor;

// in Logik
part def <'L-009'> Lastheber {
    doc /* Mechanische Einrichtung zur Aufnahme und Anheben von Ladungsträgern. */
}

// in Funktionen
action <'F-008'> lastHandhabung {
    doc /* Ladungsträger aufnehmen und abgeben. */
}

// in Logik
part def <'L-009'> Lasttragwerk {
    doc /* Mechanik zur Aufnahme und Abgabe von Ladungsträgern. */
}

// in Physik::ftf
part <'P-009'> lasttragwerk : Logik::Lasttragwerk;

// in Anforderungen
requirement <'R-008'> zweischichtbetrieb {
    doc /* Das FTF arbeitet im Zweischichtbetrieb mit 30 Minuten Ladepause zwischen den Schichten. */
}

// in Funktionen
action <'F-008'> ladepauseAusloesen {
    doc /* Das FTF selbstständig zur Ladestation fahren und dort kontaktlos laden, wenn der Akkuladestand unter 15 % ist. */
}
action <'F-009'> ladepauseAnzeige {
    doc /* Das FTF meldet den Akkuladestand mindestens einmal pro Sekunde an das Leitsystem. */
}

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das Fahrzeug selbstständig zur Ladestation fährt, wenn der Akkuladestand unter 15 % liegt. */
}

// in Funktionen
action <'F-008'> anfahrendWarnen {
    doc /* Vor dem Anfahren akustisch und optisch warnen. */
}
action <'F-009'> richtungsWechselWarnen {
    doc /* Bei Richtungswechseln akustisch und optisch warnen. */
}

// in Logik
part def <'L-009'> AkustischerWarnsounder {
    doc /* Gerät, das akustische Warnsignale emittiert. */
}
part def <'L-010'> OptischerWarnscheinwerfer {
    doc /* Gerät, das optische Warnsignale emittiert. */
}

// in Physik::ftf
part <'P-009'> akustischerWarnsounder : Logik::AkustischerWarnsounder;
part <'P-010'> optischerWarnscheinwerfer : Logik::OptischerWarnscheinwerfer;

// in Verknuepfungen
allocate Funktionen::anfahrendWarnen to Physik::ftf.akustischerWarnsounder;

// in Funktionen
action <'F-008'> stoerungenMelden {
    doc /* Das FTF meldet Störungen an das Leitsystem. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueckwaerts {
    doc /* Sensor, der Schutzfelder hinter dem Fahrzeug überwacht. */
}

// in Funktionen
action <'F-008'> warnsignalAusgeben {
    doc /* Optisches Signal zur Warnung ausgeben. */
}

// in Logik
part def <'L-009'> Warnleuchte {
    doc /* Optisches Signalgerät zur Warnung. */
}

// in Physik::ftf
part <'P-009'> warnleuchte : Logik::Warnleuchte;

// in Verknuepfungen
allocate Funktionen::warnsignalAusgeben to Physik::ftf.warnleuchte;

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das FTF fährt zur Ladestation, wenn der Akkuladestand unter einem bestimmten Niveau liegt. */
}

// in Logik
part def <'L-009'> Ladespule {
    doc /* Elektromagnetische Induktionsspule für kontaktloses Laden. */
}

// in Physik::ftf
part <'P-009'> ladespule : Logik::Ladespule;

// in Logik
part def <'L-009'> NotHaltTasterRechts {
    doc /* Sensor, der den Not-Halt an der rechten Fahrzeugseite auslöst. */
}

// in Funktionen
action <'F-008'> hindernisseRueckwaertsErkennen {
    doc /* Hindernisse und Personen im Rückwärtsgang überwachen. */
}
action <'F-009'> hindernisseVornErkennen {
    doc /* Hindernisse und Personen im Vorwärtsgang überwachen. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueckwaerts {
    doc /* Sensor, der das Schutzfeld hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerRueckwaerts : Logik::SicherheitslaserscannerRueckwaerts;

// in Verknuepfungen
allocate Funktionen::hindernisseVornErkennen to Physik::ftf.scannerVorn;

// in Funktionen
action <'F-008'> hindernisseRueckErkennen {
    doc /* Hindernisse im Rücken des Fahrzeugs erkennen. */
}
action <'F-009'> notHaltAusloesenRueck {
    doc /* Not-Halt-Taster im Rücken des Fahrzeugs betätigen, um den Not-Halt auszulösen. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueck {
    doc /* Sensor, der Schutzfelder im Rücken des Fahrzeugs überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerRueck : Logik::SicherheitslaserscannerRueck;

// in Verknuepfungen
allocate Funktionen::notHaltAusloesenRueck to Physik::ftf.scannerRueck;

// in Anforderungen
requirement <'R-008'> tragekapazitaet {
    doc /* Das FTF kann eine Masse von mindestens 2000 kg tragen. */
}

// in Funktionen
action <'F-008'> lastUeberwachen {
    doc /* Die Tragekapazität wird überwacht und bei Überschreitung des Grenzwerts gemeldet. */
}

// in Logik
part def <'L-009'> Lastsensor {
    doc /* Sensor zur Überwachung der Tragekapazität des Fahrzeugs. */
}

// in Physik::ftf
part <'P-009'> tragekapazitaetsSensor : Logik::Lastsensor;

// in Funktionen
action <'F-008'> maxGeschwindigkeitEinstellen {
    doc /* Die maximale Geschwindigkeit des FTF im Automatikbetrieb auf 3 m/s einstellen. */
}

// in Logik
part def <'L-009'> Geschwindigkeitsregler {
    doc /* Regelungssensor, der die Geschwindigkeit des Fahrzeugs im Automatikbetrieb steuert. */
}

// in Physik::ftf
part <'P-009'> maxGeschwindigkeitsregler : Logik::Geschwindigkeitsregler;

// in Verknuepfungen
allocate Funktionen::maxGeschwindigkeitEinstellen to Physik::ftf.maxGeschwindigkeitsregler;
